n.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["霸总","修真","恋爱","校园","冒险","搞笑","生活","热血","架空","后宫","玄幻","悬疑","恐怖","灵异","动作","科幻","战争","古风","穿越","竞技","励志","同人","真人"
]
	arList.map((tag,index)=>{
		url=`http://comic.mkzcdn.com/search/filter/?page_num={{page}}&page_size=12&theme_id=${index+1}`;
		push(tag, url, 1, 0.25);
		});
		push("🌊状态🌊",null,1,1);
		push("连载",`http://comic.mkzcdn.com/search/filter/?finish=1&page_num={{page}}&page_size=12`,1,0.35);
		push("完结",`http://comic.mkzcdn.com/search/filter/?finish=2&page_num={{page}}&page_size=12`,1,0.35);
		push("🌊类型🌊",null,1,1)
		nrList=["少年","少女","青年","少儿"
]
nrList.map((tag,index)=>{	url=`http://comic.mkzcdn.com/search/filter/?audience=${index+1}&page_num={{page}}&page_size=12`;
	push(tag,url,1,0.25)
	});
	push("🌊题材🌊",null,1,1)
		orList=[["免费","is_free"],["付费","is_fee"],["VIP","is_vip"]]
orList.map([tag,ure]=>{	url=`http://comic.mkzcdn.com/search/filter/?${ure}=1&page_num={{page}}&page_size=12`;
	push(tag,url,1,0.25)
	});
//java.log(JSON.stringify(sort))
JSON.stringify(sort)

